function Stat({label,value,icon,sub,alert=false}:{label:string;value:number|null;icon:React.ReactNode;sub:string;alert?:boolean}){return <div className={`stat ${alert?'alert-stat':''}`}><div className="stat-label">{label}<span>{icon}</span></div><strong>{value===null?'…':value.toString().padStart(2,'0')}</strong><p>{sub}</p></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function NativeSelect({name,items}:{name:string;items:readonly string[]}){return <Select name={name} defaultValue={items[0]}><SelectTrigger className="w-full" aria-label={name}><SelectValue/></SelectTrigger><SelectContent>{items.map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select>}
function IntegrationCard({integration:i,children}:{integration:Integration;children:React.ReactNode}){return <article className="panel integration-card"><div className="integration-top"><div className={`integration-icon ${i.kind}`}>{i.kind==='ai'?<Sparkles/>:i.kind==='mis'?<Layers3/>:i.kind==='ehr'?<Stethoscope/>:<ShieldCheck/>}</div><Tag tone={i.status==='active'?'success':i.status==='suspended'?'amber':'neutral'}>{i.status==='unconfigured'?'Not connected':i.status==='active'?'Active profile':'Suspended'}</Tag></div><span className="integration-kind">{i.kind==='ai'?'AI PROVIDER':i.kind==='mis'?'PROGRAMME MIS':i.kind==='ehr'?'ELECTRONIC HEALTH RECORD':'HEALTH INFORMATION EXCHANGE'}</span><h2>{i.name}</h2><p>{i.description}</p><div className="tags"><Tag tone={i.mode==='demo'?'blue':'neutral'}>{i.mode==='demo'?'Demo adapter':i.mode==='http'?'HTTP API · credentials required':'Onboarding required'}</Tag><span className="muted text-sm">v{i.version}</span></div>{i.endpoint&&<small className="endpoint">{i.endpoint}</small>}<div className="integration-actions">{children}</div></article>}
function ReceiptList({data,busy,command,onReceipt,visitId}:{data:Snapshot;busy:boolean;command:(c:any,s?:string)=>Promise<any>;onReceipt:(id:string)=>void;visitId?:string}){const {t,lang,signOff}=useI18n(),en=lang==='hi'?'en':undefined;const [tab,setTab]=useState('all'),panelId=useId();const list=submissionList(data.submissions.filter(s=>!visitId||s.visitId===visitId),tab==='attention'),rows=list.rows;return <section className="panel receipt-panel"><Tabs value={tab} onValueChange={setTab}><div className="section-heading"><TabsList variant="line"><TabsTrigger value="all" aria-controls={panelId}>{t('receipts.all',{n:list.all})}</TabsTrigger><TabsTrigger value="attention" aria-controls={panelId}>{t('receipts.attention',{n:list.attention})}</TabsTrigger></TabsList></div></Tabs><div id={panelId} role="tabpanel" aria-label={tab==='attention'?t('receipts.ariaAttention'):t('receipts.ariaAll')}>{rows.length?rows.map(s=><div className="receipt-row" key={s.id}><div className={`receipt-icon ${s.state==='accepted'?'ok':'warning'}`}>{s.state==='accepted'?<CheckCheck/>:<Clock3/>}</div><div className="receipt-main"><strong>{s.connectorName}</strong><span>{data.people.find(p=>p.id===s.personId)?.name} · {formatDate(s.createdAt)}</span><p lang={en}>{s.message}</p><small>{s.receipt??t('receipts.notConfirmed')} · {t('receipts.attempts',{n:s.attempts,mode:s.mode==='demo'?t('receipts.modeDemo'):'HTTP API'})}</small><small className="block">{t('receipts.signOff',{text:signOff(s.signOff)})}</small><DeliveryActions s={s} busy={busy} command={command}/></div><div className="receipt-actions"><Tag tone={s.state==='accepted'?'success':'amber'}>{t(`common.state.${s.state}`)}</Tag>{s.mode==='demo'&&s.state==='uncertain'?<Button variant="outline" disabled={busy} onClick={()=>command({type:'reconcile',submissionId:s.id},t('receipts.lookupDone'))}><RefreshCw size={15}/>{t('receipts.lookup')}</Button>:<button className="text-link" onClick={()=>onReceipt(s.id)}>{t('receipts.view')} <ChevronRight size={14}/></button>}</div></div>):<Empty title={tab==='attention'?t('receipts.emptyAttentionTitle'):t('receipts.emptyAllTitle')}>{tab==='attention'?t('receipts.emptyAttentionBody'):t('receipts.emptyAllBody')}</Empty>}</div></section>}
